INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1023081-ee207', 'stk-user6410', 'EE 207', 'info', '{"desc": "جودة المقرر بشكل عام: جيد جدا مرتفع يغطي أساسيات الإتصالات والتحكم\nالمواضيع التي يغطيها المقرر: معادلات فورير (الإتصالات ee370) و (لابلاس التحكم ee380) والكنفلوشن\nالكتاب المستخدم للمقرر: جيد لكن غير كافي ويعتبر مرجع فقط\nالأسئلة والأمثلة المستخدمة في المقرر: جيدة\nمدى فائدته في الناحية التطبيقية: المادة ذات فائدة عظيمة ويتحتم عليك فهمها بشكل لايقل عن جيد جدا مرتفع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/3", "user": "user6410", "ts": 1334522526000, "tid": 120699, "pn": 3}}', 1334522526000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1032453-ee207', 'stk-m7mud', 'EE 207', 'info', '{"desc": "اذا اخذت الماده لاتضيع ميجر 1\nلأنه غالبا الطلاب يحسبو الماده سهله\nلاكن لا جا الميجر ضاعوا وما عرفو من فين يبدأو\nعشان كذا اعطي ميجر 1 وقت زياده عن المواد الثانيه\nلأنه ماده فكرتها جديده عليك\n\nواذا عرفت طريقة مذاكرة الماده ميجر2 والفاينال سهلين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/4", "user": "m7mud", "ts": 1336168298000, "tid": 120699, "pn": 4}}', 1336168298000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1045997-ee207', 'stk-user7062', 'EE 207', 'info', '{"desc": "هذه المادة تعتبر أساس في هندسة الاتصالات … أنصح أي أحد يأخذ الكورس هذا التركيز في ميجر 1 بشكل خاص … لأن المادة تعتبر صعبة نسبيا … بل هي أصعب مادة في ليفل 2", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/5", "user": "user7062", "ts": 1338118053000, "tid": 120699, "pn": 5}}', 1338118053000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1049041-ee207', 'stk-user6095', 'EE 207', 'info', '{"desc": "المقرر يتحدث عن\n\nأنوآع الـ Signals و الـ Systems\n\nو كذلك الـ convolution و خواصه …\n\nFourier & Laplace Transforms, and z-transform\n\nالمنهج بـ شكل عآم غير سهل … و كذلك غير صعب …\n\nو كذلك المنهج مآ هو طويل … و غآلبآ مآ يكون فيه تكرآر …\n\nو زي مآ قآلوآ الأخوآن (( كورس مآث )) …و ممتع جدآ …\n\nالـ Self Study … غير مجدية نوعآ مآ مع هذآ الكورس … لـ ذلك انصح بأخذ الكورس مع دكتور شريح … و كذلك الإنتبآه مع الدكتور …\n\nيعتبر أحد أصعب الموآد في الـ 2 ليفل … لكنّه أمتعهــآ … مع الـ 200", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/6", "user": "user6095", "ts": 1338568920000, "tid": 120699, "pn": 6}}', 1338568920000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1382410-ee207', 'stk-user8577', 'EE 207', 'info', '{"desc": "Ee207\n\nمثل ما قالوا الشباب كورس 99% ماث … كورس بتحتاج أشياء منه لل ee370 و ee380.\n\nالمواضيع التي يغطيها المقرر:\n\nبشكل عام الكورس يعلمك كيف تتعامل مع الsignals في domains مختلفة وايش يصير للsignals مع الsystems المختلفة وخواص هذي ال systems.\n\nالكتاب المستخدم للمقرر:\n\nالكتاب واضح بس ما كنت استخدمه كثير لان حتى الدكاترة يعتمدوا على نوت الجامد في الشرح … أيضا نوت مقيبل مفيد.\n\nالمادة صعبة وتحتاج جهد … بداية الكورس بتحسه سهل كثير أشياء من ماث الأوريا بس بعدها المادة تصعب تدريجيا … المواضيع فيها تشابه بمعنى انك تدرس نفس الأفكار في Domains مختلفة هذا يسهل شوي على الطالب … لما قلت المادة صعبة ما يعني ما تنفهم بس يبغى لها وقت وجهد فدراسة متأخرة قبل الاختبار ما تفيد.\n\nالفاينال عليه 40% يعني نسبة كبيرة بس في نفس الوقت اصعب من المياجر. في الفاينل او المياجر الخيارات كانت اصعب شي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/8", "user": "user8577", "ts": 1403691226000, "tid": 120699, "pn": 8}}', 1403691226000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473929-ee207', 'stk-mr.a1', 'EE 207', 'info', '{"desc": "Term 162 with HUSAIN ALJAMED\n\nجودة المقرر بشكل عام\nمقرر أساسي للمهتمين بهندسة الاتصالات ، وحتى أصحاب هندسة التحكم لهم نوع من الارتباط مع المادة.\n\nالمواضيع التي يغطيها المقرر\nالمادة دسمة بشكل ، وفيها مواضيع كثيرة:\nContinuous-Time Signals\nConvolution\nSystems & Their Classifications\nLTI Systems\nFourier Series\nFourier Transform & Its Applications\nFilters & Bandwidth\nLaplace Transform & Its Applications\nFunctions’ Sampling\nDiscrete-Time Signals\nZ-Transform & Its Applications\n\nالكتاب المستخدم للمقرر\nالكتاب ممتاز للمذاكرة والفهم ، ممكن يعيبه إنه مصمت وكتابته صغيرة اشوي.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nأمثلة الكتاب والأسئلة في نهاية كل تشابتر جيدة ، لكن بتحتاج تمر على Old Exams إذا كنت تبي تجيب +A\n\nمدى فائدته في الناحية التطبيقية\nمادة مهمة وأساسية في التخصص ، بالأخص للأشخاص المهتمين بهندسة الاتصالات ومعالجة الاشارات والأنظمة اللي تمر فيها.\n\nملاحظات:\n١. مثل ما شفت المادة دسمة جدا ، مهم جدا إنك تذاكرها أول بأول وما تستهين فيها ، وإلا كل شيء بيتراكم عليك وتتورط.\n٢. إحرص على الدكتور الممتاز في هذه المادة ، وإلا راح تتعب كثير.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/9", "user": "Mr.A1", "ts": 1495926489000, "tid": 120699, "pn": 9}}', 1495926489000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1491890-ee207', 'stk-abdullah2015', 'EE 207', 'info', '{"desc": "أخذت الكورس في ترم 172 مع الدكتور عزالدين زرقوين\n\nجودة المقرر بشكل عام:\nممتازة، لكن أعيب فيه إنهم مهملين الجانب التطبيقي إلى حد كبير ومركزين على الرياضيات أكثر شيء في عرض المواضيع. الدكتور اللي درسني المادة ما قصر كان يحاول قدر الإمكان إنه يربطها بالواقع لكن هذي جهود شخصية منه وهو ملزوم بإنه يخلص المنهج، فما كان يقدر يتوسع في هذا الجانب كثير نظرًا لضيق الوقت.\n\nالمواضيع التي يغطيها المقرر :\nالأخوة اللي قبلي ذكروا المواضيع، لكن ما أعتقد إن واحد ما درس المادة ممكن يفهم إيش المقصود منها.\n\nباختصار، المادة (كما أراها) تركز بشكل أساسي على تحويلات Fourier Series, Fourier Transform, Laplace Transform ، التحويلات هذي تساعدنا في حل (أو تبسيط) الأنظمة (أو المعادلات) المعقدة.\n\nمثلًا، ممكن تحل معادلة تفاضلية باستخدام Fourier Transform أو Laplace Transform وراح تكون أسهل بكثير من حلك لها بالطريقة العادية التقليدية.\n\nطبعًا فيه مواضيع ثانية مهمة ولكن أحس إنه هذي التحويلات هي زبدة الكورس 🙂\n\nالكتاب المستخدم للمقرر:\nhttp://www.pearson.com.au/MC_images/_amazon/9781292015286.jpg\nhttp://www.pearson.com.au/products/O-R-Phillips-Charles-et-al/O-R-Phillips-Charles-Et-Al/Signals-Systems-Transforms-Global-Edition/9781292015286?R=9781292015286\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nأمثلة وأسئلة الكتاب مفيدة جدًا في ترسيخ المفهوم، لكن ما تكفي للمذاكرة للاختبارات، لازم تشوف أولد إقزام.\n\nمدى فائدته في الناحية التطبيقية:\nالمقرر يعتبر أساسي للمهتمين بالاتصالات EE370 ، وكذلك للمهتمين بالتحكم EE380 نوعًا ما.\n\nملاحظات:\n- الكورس هذا أصنفه من نوع السهل الممتنع، يعني الكونسبت اللي فيه تحسه سهل، لكن بمجرد ما تبدأ تحل في سؤال توصل لمرحلة تعلّق ما تعرف كيف تكمل، فتضطر تشوف السلوشن، ولما تشوف السلوشن وتعرف الحل، تشوف إن الحل سهل، أو إنك تحل السؤال وتظن إن حلك صح، لكن في الأخير لما تراجع السلوشن تكتشف إنه فيه خطوة معينة غير مسموح إنك تطبقها على الحالة هذي أو المفروض تطبقها بطريقة مختلفة. المنهج أغلبه كان زي كذا بالنسبة لي. المشكلة هي إن على كل فكرة فيه عدة حالات، فلازم تحل أسئلة كثير عشان تغطي الحالات كلها (إذا كنت تطمح للA+).\n\nيعني كل أخطائك اللي راح تسويها في الكويزات والمياجر والفاينل غالبًا راح تحس إنها تافهة بعد ما تشوف السلوشن 🙂\n\n- الكورس بطريقة عرضه الحالية أعتبره كورس ماث، فالتدريب مهم جدًا.\n\n- فيه بروجيكت في الكورس على الMATLAB … درجة صعوبته أو سهولته تعتمد على دكتورك، لكن بشكل عام أشوف إن البروجيكت في هذي المادة سهالات.\n\nبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/10", "user": "Abdullah2015", "ts": 1525645739000, "tid": 120699, "pn": 10}}', 1525645739000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1503585-ee207', 'stk-_sultan_alshardi', 'EE 207', 'info', '{"desc": "كما قال اخواني الي سبقوني المادة مهمة جدا وتعتبر هي البداية الفعلية للهندسة الكهربائية سواء مجال الاتصالات او اي مجال اخر. نصيحتي باعطاء اهمية وجهد اكبر لهذه المادة ومحاولة فهمها.\nمن باب المشاركة في نشر العلم سوف انسخ لكم رابط شرح للمادة قمت برفعة على قناتي في اليوتيوب واتمنا تكون مفيدة لكم\n\nhttps://www.youtube.com/watch?v=rmvfpYiKX6M", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-signals-and-systems/120699/11", "user": "_Sultan_Alshardi", "ts": 1544803081000, "tid": 120699, "pn": 11}}', 1544803081000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1337827-ee207', 'stk-abo-zahrah', 'EE 207', 'info', '{"desc": "ههههههههههههههههههههههههههههههههههههه\nكتبت التعليق الساعة 3 بالليل وكنت زعلان مرة لاني ذاكرت والله لكن وش نقول الاختبار والله كان صعب ومو متوسط لاتظن يوم انك حليت زين انه متوسط\nوالله حتى الخيارات فيها تركات بالهبل وطويييييييييييييييييييييييييييييييييييييييييييييييل\nلكن يالله معوضين ولاننسى في شيئ لصالحنا الفاينال عليه 40 من الكورس وكلاس وورك عليه 20 يعني بحسبة بسيطه طلعت بمجموع في المياجر 24 من 40\nوكلاس وورك 16 من 20\nوبما ان اول فاينال اتوقع 207 يعني بتبدع فيه قبل ماتنفس وبتجيب 30 من 40 مجموعك 70 يعني تقريبا b\nطبعا قلت انو b لان اغلب مواد الكهرب الافرج ينزل كل قريد تقريبا من (3,-3)\nفلانفقد الامل 👍 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207/157956/8", "user": "Abo-Zahrah", "ts": 1394184553000, "tid": 157956, "pn": 8}}', 1394184553000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p841987-ee207', 'stk-barhomitto', 'EE 207', 'info', '{"desc": "والله صعب صعب صعب …\nوانا (الي عايد المادة) أقول يارب سترك بس لا … لا اله الا الله\nالسؤال الثاني قاعد أفحط أفحط أفحط فيه مادريت الا الدكتور يقول باقي 25 دقيقه !!\nالله كريم ياخوي سلطان عل وعسى انهم خلاص طيحو الي بروسهم ويجي الفاينل سهل إن شاء الله\n\nبالنسبة للي يرفع الافرج … هذولا ياخوي ما يجون هنا ويقولون صعب\nهذا اصلا ماعنده وقت يضيعه في المنتدى\nتلقاه ماسك الكتاب وقاعد يذاكر للفاينل من الحين\n\nالله يوفقنا وياهم لاحسد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-ee-207/107333/4", "user": "Barhomitto", "ts": 1304857451000, "tid": 107333, "pn": 4}}', 1304857451000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p842111-ee207', 'stk-s.u.l.t.a.n', 'EE 207', 'info', '{"desc": "الله يوفقكم جميعا يارب.\n\nيالله اتوقع, ما بيطولون و ينزلون الدرجات نفس الميجر 1.\n\nعالعموم, هالماده مع ان اسئلتها شوي لحسه, و كل اللي نسمع قبل انها صعبه. بس احس من جد الماده بشكل عاااام جدا سهله, بس الجامعه عجيبه, لو تكون اتفه ماده, لازم يصعبونها, يا باختبارات صعبه, يا بهالافرج اللي يضر اكثر مما ينفع. و بالذات قسمنا.\n\nالاقسام الثانيه مرتاحين, حتى نفسياتهم تمام, احنا بعذاب لحد ما ننتهي, تجيب 70 تاخذ سي , وين عايشين. والاقسام الثانيه ال 70 بي. !!!\n\nدمتم بسعاده,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-ee-207/107333/6", "user": "S.U.L.T.A.N", "ts": 1304870027000, "tid": 107333, "pn": 6}}', 1304870027000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p809385-ee207', 'stk-sstem', 'EE 207', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nزملائي واخواني الغالين,\n\nحبيت اسئلكم من وين نذاكر مادة ee207\nالصراحه ما ندري من وين نذاكر\nمافيه شيء واضح\nالكتاب موب واضح\nوسلايدات بال غنيم موب كامله فيه اشياء ما لقيتها\nوونوتة الدكتور الجامد برضوو موب واضحه مره\n\nاذا تساعدونا يا من جربتوو هذي الماده\nوالف شكر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/104444/1", "user": "sstem", "ts": 1299611418000, "tid": 104444, "pn": 1}}', 1299611418000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p975602-ee207', 'stk-saqer-aljazera', 'EE 207', 'info', '{"desc": "السلام عليكم\n\nللاسف ديبارتمنت الكهرب رفض الابروفل لماده Ee207 ما أدري ايش بالضبط المطلوب مني\n\nوش ذنبي ما آخذ الماده مع انها أساسيه ومهمة جدا\n\n500 ريال للي يجيب لي الكورس ee207 بس يكون كورس الساعه 9 لانه الوحيد الي مافيه كونفلكت مع باقي الجدول\n\n0504555583\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/119196/1", "user": "saqer-aljazera", "ts": 1327802264000, "tid": 119196, "pn": 1}}', 1327802264000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p860474-ee207', 'stk-user4571', 'EE 207', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nصبحكم // مساكمـ الله بالخير والمسرااات…, 🤴\n\nكيفكم وكيف الصيفي والحرر والمذاكراة :sneezing_face:\n\nيا اخواني يا اصحاب الخبرة بــ 207\n\nحبيت استفسر عن افضل طريقة لمذاكرتها لاني حاولت افتح الكتاب سدددددددددد نفسي\n\nوخبركم المادة طوييييلة والله يعين عليها بالصيف\n\nوما بووه كورس اون لاين بالويب سيتي\n\nهل فيه نوتات بالجمعية…’\n\nهل فيه سلايدات بالنت ولا كيف\n\nافيدوونا ولكم جزيل الشكر والعرفان .: ❤️\nوالتقييم بعد ولا تزعلوون… 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/109138/1", "user": "user4571", "ts": 1309231671000, "tid": 109138, "pn": 1}}', 1309231671000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p861166-ee207', 'stk-extensa', 'EE 207', 'info', '{"desc": "انا اشوف افضل طريقة انك تسجل نوت مع مدرسك وتفهم معه بالكلاس 🤴 … خصوصا بهالمادة لاتحاول تسرح ولاتهوجس والمدرس يشرح 🤪 … لان مثل ماتعرف الكتاب سئ سئ جدا لانه يعقد الامور بعض الاحيان واحيان يبدأ يشرح لك في شئ في غير وقته “يعني يستبق الامور”\nفزي ماقلت لك احرص على النوت + الفهم + الي انا اعرف ان لمداة ذي مافيها تسليم هوموركات لكن بعد ماتخلص من دراستك افتح اسئلة الهومورك وحلها وقارن حلك مع السليوشن 👍 …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/109138/8", "user": "extensa", "ts": 1309346893000, "tid": 109138, "pn": 8}}', 1309346893000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p373497-ee207', 'stk-c000524133', 'EE 207', 'info', '{"desc": "انا طالب زائر من جامعة الامير محمد ودرست الفصل الماضي(082)مع الدكتور الفاضل محمد دريش (ee207) وكان يهمني فهم الماده لان درجة الماده ليست محسوبه بجامعة الامير محمد مجرد باس او fail والحقيقه اقسم بالله وشهاده حق ان الدكتور عظيم واستفدت في فهم الماده الشي الكثير وادين له بالفضل الكثير بعدالله كما اتمنى ان ادرس مواد اخرى مع نفس الدكتور لانه مكسب لنا وللجامعه كما انصح من يريد فهم الماده ان يدرسها مع الدكتور لانه يراعي الله في شرحه وكذلك لا يظلم الطالب ويحرص على مصلحة الطالب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207/70940/2", "user": "c000524133", "ts": 1235674924000, "tid": 70940, "pn": 2}}', 1235674924000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1325638-ee207', 'stk-mr.mohammed', 'EE 207', 'info', '{"desc": "الصراحة الكورس لمن اخذته , ماكان في اي سورس يقارن بالكتاب , صحيح الكتاب صعب فهمه ويحتاج وقت , لكن مدامك من بداية السمستر فحاول تقرا من الكتاب وتفهم , لانه في اشياء يشرحها الكتاب تفهمك الكونسيبت اكثر من اي سورس ,\n\nوحل الاسئله عندك تمارين نهاية الكتاب والاولد اكزامز وكويزات د.حسن المقيبل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/156086/15", "user": "Mr.Mohammed", "ts": 1391360994000, "tid": 156086, "pn": 15}}', 1391360994000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p989087-ee207', 'stk-user8735', 'EE 207', 'info', '{"desc": "انا جالس اخد المادة الحين… انا اشوف اذا تبي تفهم الماده , اول شئ حضر الدرس قبل تروح للكتشر مع الدكتور حقك… خد لك فكرة عن الدرس واقراه بهدوء بدون استعجال على فهم المعلومة … احضر الدرس وشوف النوت والنقاط الي طرحها الدكتور وقارنها بالموجود بالكتآب… وانت ناقشه بالاوفس اور بالاشياء الي ماتطرق لها …\nاذا خلصت الدرس او التابتشر حل الاسئلة الواجب وبعض الاسئلة الكتآب والمبهم عليك راجعه مع مدرسك… حل كويزاات مدرسين ثانيين زي بوغنيم عنده ماتيريال جدآ رائع … وبهالشكل انت تكون غطيت المادة … الكتآب اولآ ثم نوتة المدرس مع حل الاسئلة بشكل دوري وبنهايةالمطآف عندك اولد اقزام تكون اخر الرحلة وبهذآ تضمن a+ باذن الله … توكل على الله ولولآ توفيق الله لكان اول مايجنى علينا اجتهآدنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/121178/10", "user": "user8735", "ts": 1329604873000, "tid": 121178, "pn": 10}}', 1329604873000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p529744-ee207', 'stk-azzoooz', 'EE 207', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nشباب وبعدين مع هذي المادة هي وكتابها الغير مفيد جدا\n\nفترات أحس انها سهلة ولما أرجع البيت وأبي أذاكرها أضيع وأروح وطي\n\nوبالنسبة للكتاب فهو سيء جدا مافيه تمارين ولا مسائل زي الأوادم\n\nما أقول إلا الله يعين بس\n\nمن هنا أقول اللي عنده أي حاجه من ملخصات أو اختبارات فلا يبخل علينا\n\nلأن من جد ما أعرف من وين أذاكر لها\n\nودمتم في صحة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207/82682/1", "user": "azzoooz", "ts": 1264551226000, "tid": 82682, "pn": 1}}', 1264551226000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p95884-ee207', 'stk-user1574', 'EE 207', 'info', '{"desc": "خذهم شرح\nغير كذا لاتدور قريدات عندهم وخصوصا الأخضر\nبالغنيم مايعطي F بس عنده مقولة دايما يحب يقولها في الكلاس\n( القريدات مو هنيه القريدات في حديقة الحيوان) ويقعد يضحك طول الحصة على هذه المقولة المأثورة بالنسبة له\nع العموم أنا أعرف واحد شد معاه وبدع في المياجر والكويزز وفي النهاية +c في مادة 207\nوجاك اضطر أنه ياخذ معاه 315 وأحبط فقام طنش المادة ولا صار يحضر وطلع في الأخير D\nرغم أنه يقولي ماجبت أعلى من 40 في المجموع النهائي\nعشان كذا قلتلك أنه مايعطي F\nأتمنى أكون أفدتك\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/50394/2", "user": "user1574", "ts": 1145831325000, "tid": 50394, "pn": 2}}', 1145831325000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1054866-ee207', 'stk-user4870', 'EE 207', 'info', '{"desc": "الكتاب ممتاز برايي !\nصدقني لو تقعد عليه وتطقطق مع الشرح والامثلة ومن ثم البروبليمز (يفضل وجود السلوشن لها) انك ان شاء الله تفهم الكونسبت , ما اقول 100% لكن 70% ,\nوالباقي حل مياجر قديمة لان الكورس صراحة فيه افكار كثير و ما يغطيها الكتاب لكن المياجر القديمة تغطي جزء من هالافكار .\nشف سلايدات بعض الدكاترة - اظن بالغنيم ان ما كنت ناسي - وايضا شيّك على بقية الدكاترة .\nبالاخير الكتاب جيد ولازم تقراه.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207/127434/2", "user": "user4870", "ts": 1339567847000, "tid": 127434, "pn": 2}}', 1339567847000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1104170-ee207', 'stk-user5882', 'EE 207', 'srcP', '{"html": "هذا هوموورك شبتر 3 في المرفقات<br><br>​<span data-fid=\"stk-f1104170-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1104170-0": {"name": "RelativeResourceManager.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/555292086782acbc0edb0e23b69f2188546f4f9a77cf8c572ac8359d62185172"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-207-121/132784/13", "user": "user5882", "ts": 1349559945000, "tid": 132784, "pn": 13}}', 1349559945000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p954412-ee207', 'stk-user7855', 'EE 207', 'srcU', '{"html": "الملف بالمرفقات<br><br>​<span data-fid=\"stk-f954412-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f954412-0": {"name": "EE 207 Course Project (111).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/6ebf3f72ee4db96c64d9df14dbe8bdc5a93a785b12df64d06c15b5209fd1eab0"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207-course-project/117103/3", "user": "user7855", "ts": 1325011381000, "tid": 117103, "pn": 3}}', 1325011381000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p956147-ee207', 'stk-imported1', 'EE 207', 'srcU', '{"html": "السلام عليكم …<br><br>تفضل … في المرفقات … حل الفقرة a و b<br><br>في الجزء الأول … و الفقرات الباقية … نفس الطريقة … فقط تغير الدالة و اسمها …<br><br>أتمنى أن تكون عندك خلفية و لو بسيطة في الماتلاب …<br><br>بمعنى … كيف تدخل للماتلاب … و كيف تستخدم Matlab window أو M-file<br><br>و إذا لقيت وقت … إن شاء الله أحاول في الأسئلة الباقية …<br><br>فقط … انسخ الكود اللي في الملف للماتلاب و اعمل له run<br><br>المقابل … دعوة في ظهر الغيب …<br><br>​<span data-fid=\"stk-f956147-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f956147-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f956147-0": {"name": "part_1, a&b.txt", "v": "data:application/octet-stream;base64,"}, "stk-f956147-1": {"name": "part_3.txt", "v": "data:application/octet-stream;base64,DQoNCmZvciBUcz0wLjAwMjowLjE6MQ0KDQogICAgU1I9MS4vVHM7DQoNCiAgICB0PTA6VHM6MTsNCg0KICAgIHg9Y29zKDIqcGkqMTAqdCk7DQoNCiAgICBwbG90KHQseCwnLi0nKQ0KDQogICAgdGl0bGUoJ1JzJykNCg0KICAgIHBhdXNlDQoNCmVuZA0KDQo="}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207-course-project/117103/5", "user": "imported1", "ts": 1325286904000, "tid": 117103, "pn": 5}}', 1325286904000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p978315-ee207', 'stk-user5697', 'EE 207', 'srcU', '{"html": "تفضل … في المرفقات<br><br>​<span data-fid=\"stk-f978315-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f978315-0": {"name": "New WinRAR ZIP أرشيف.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/599c5f1ead1d9b30e2074b14a517f85b63cc2fdee8cdbe03297bdb921ff5cd13"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wanted-dead-or-alive-ee207-syllabus/119544/2", "user": "user5697", "ts": 1328157017000, "tid": 119544, "pn": 2}}', 1328157017000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p960871-ee207', 'stk-_763', 'EE 207', 'srcP', '{"html": "السلام عليكم<br><br>هذي فاينال اكزام حق 2010 و 2009 لكن غير محلولة للأسف، بس مفيدة لمعرفة كيفية الأسئلة وصعوبتها<br><br>وبالتوفيق<br><br>​<span data-fid=\"stk-f960871-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f960871-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f960871-0": {"name": "EE207_082_FINAL.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/ef27171b2e6c000ccb17b16e6b7de83e455a3c80b5ef0a0616a1996c19d4bd5a"}, "stk-f960871-1": {"name": "EE207_Final_091.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/355cb3be733d4a510298f22e961382ed727c26d163180ae892f4e9c147fc3e02"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee207-2010-2009-final-exams/117656/1", "user": "_763", "ts": 1325937364000, "tid": 117656, "pn": 1}}', 1325937364000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee207', 'stk-user6130', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98376", "n": "Dr. K Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله ،،،\nee 207 سمستر 111 ،،،\nالشرح : ملك 🤴 من أفضل الدكاترة في إيصال المعلومة و يكتب نوت مدعم بأمثلة روعة إذا ذاكرتها ما راح يقل قريدك عن b+ إن شاء الله بس فيه عيب وحيد إنه بعض الأحيان يسرع في الشرح بس إذا قلت له عيد يعيد ما عنده مشاكل.\n\nالتحضير : ورقة و يمديك تحضر اللي تبي.\n\nالكوزات : سهلة جداً يجيبها في الغالب من موقع الدكتور بالغنيم.\n\nالمياجر : كومن و كذلك الفاينل .\n\nإضافات :\n* عطانا بروجكت سهل جداً و قصير و أعطانا مدة كافية للتسليم و مددها.\n* تصحيحه عسل بس ذا السمستر صار يتبع السلوشن بحاذفيره بس إذا كلمته ما راح يقصر.\n* قمة في الأخلاق و أتعب و أنا أقول أخلاق.\n* باختصار إذا شفته في أي كورس نزل عنده و ما راح تندم.\n\nالقريد النهائي : +A.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970921-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-qureshi/98376/13", "user": "user6130", "ts": 1326985461000, "tid": 98376, "pn": 13}}]}', 1326985461000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-ee207', 'stk-abo-da7m', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98377", "n": "Dr. S. Al-Ahmadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE207 فصل 142\n\nالتحضير :\n\nكنا بس 9 طلاب ،، ما كان يحضر لمين جا الميجر وشاف طالب ما عرفه قال من انت قال انا من طلابك ! هههه - ما يحضر أبد 🙂 - بعده بدأ يحضر\n\nطريقة الشرح :\n\nيفتح الكتاب ويكتب العناوين الرئيسة ويجلس يسولف عنهن، يعطي تمرين وينتظر الطلاب يحلونه ويشوف حللهم (ممكن سواه معنا لأننا قليلين)\n\nبكشل عام ما يشرح قد ما يسولف ويعتبر أن اللي قدامه فاهم عليه\n\nالكويزات :\n\nسهلة عطانا حول 5\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nC+\n\nالصوت:\n\nواضح ،، لغته زينة. ما يتكلم عربي أبد لدرجة أني استغربت يوم قال كلمة عربي بنص الفصل 🙂\n\nإضافات :\n\n* الدكتور باين عليه فاهم بس مشكلته ما يشرح ويفترض أن اللي قدامه فاهمين وهم بس يناظرون ولا يدرون شيقول !\n\n* ما أشوفه يبذل جهد كثير عشان يفهم اللي قدامه ،، يفتح الكتاب pdf ويعلق عليه ويجاوب على أسئلة الطلاب إذا فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433424-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-al-ahmadi/98377/25", "user": "abo-da7m", "ts": 1447639942000, "tid": 98377, "pn": 25}}]}', 1447639942000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abaadi-ee207', 'stk-abaadi', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98377", "n": "Dr. S. Al-Ahmadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE207\nterm - 202\nOnline\n\nالتحضير: كان ماله وقت محدد ومفاجئ\n\nالشرح: بصراحة الدكتورما يعرف يوصل المعلومة ابدا مع انه يحاول لكن للاسف في مشكلة بايصال المعلومة للطالب ف الاستفادة من الحصة الخروج منها بمعلومات خاصة بهذي المادة اللي تحتاج تركيز عالي كان قليل جداااا. وكان صراحة اكثر من حصة يقرا من الكتاب اوالنوتات .\n\nالكويزات: كويزاته كانت اذكر ريتين كلهم بس بصراحة يعطيك الدكتور نوعا ما فيها درجة على اللي تكتبه partial credits وذا كان شيء حلو بصراحة وكان مستوى الكوازات قريب المتوسط وفي اكثر من كويز كان مستوى سهل.\n\nالمياجر/ المدات/ الفاينل: كومون\n\nالصوت: منخفض وبالانجليزي\n\nالتقييم االعام: C\n\nاضافات: الدكتور متعاون تقريبا و حبيب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531510-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-al-ahmadi/98377/33", "user": "Abaadi", "ts": 1630013152000, "tid": 98377, "pn": 33}}]}', 1630013152000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8577-ee207', 'stk-user8577', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee207\n\nبنود التقييم :\n\nالتحضير : آخر الكلاس.\n\nطريقة الشرح : سمعة الدكتور انه شريح بس في الكورس هذا الوضع مو مرة 🤪 … الدكتور يستخدم نوتات الجامد … الواقع هو ينسخ نوت الجامد على السبورة ما أقولك انه ما بتفهم منه بهالطريقة بس تحس ان الدكتور مو فاهم اذا طلع برا النوت … أنك تكتب وراه النوت ما تلحق و ما تركز و أنك تجيب معك النوت جاهز وتمشي معه عليه بتزهق عيشتك خاصة اذا كلاس ساعة وربع 😦 😢\n\nالكويزات : سهلة إلى متوسطة.\n\nالمياجر: كومن\nالفاينلات : كومن … خذها قاعدة فاينالات الكهرباء صعبة\nتصحيحه يعطيك حقك.\n\nالصوت: واضح بس نبرة وحدة تمل.\n\nإضافات : الدكتور أخلاق و تعامله كويس مع الطلاب في المكتب … واضح في كورسات ثانية الدكتور جيد بس 207 مو مرة … ما اعرف هي المشكلة في المادة ولا الدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1381658-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/23", "user": "user8577", "ts": 1403393273000, "tid": 98387, "pn": 23}}]}', 1403393273000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-man.moh-ee207', 'stk-man.moh', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 182 EE207\nTerm 182 EE203 LAB\nبتكلم عنه اول بال EE207 وبعدها باللاب .\n\nالتحضير :\n\nيحضر اخر الحصة , بس لو جيت متأخر 5 الى 10 دقايق يحطك ليت.\nطريقة الشرح :\n\nيشرح اشوي كونسبت , والباقي يقعد يحل امثله كثيره لين الفكرة توصل للأغلب, انصحك تكتب معاه بالكلاس لأن طريقته بالحل أوضح من نوته دكتور الجامد.\nالكويزات :\n\nنفس الأسئلة الي يحلهم بالكلاس, ذاكرهم وافهم تمام وانشاءلله بتجيب فل.\n\nالمياجر:\nكان هو الكوردنيتر , اول ميجر كان الافرج 25 من 40 , الميجر الثاني 31 من 40 , تصحيحه فيهم اشوي شديد, يمشي على منوال السولشن ويحاسب على النص والربع, يعني يعطيك حقك فقط.\nالفاينلات :\nماكان ذاك الصعوبة , ولكن الماده نفسها اشوي صعبه وتحتاج حل وممارسة.\nالقريد النهائي:\nB+\nالصوت:\nجدا جدا واضح , ويتكلم انجلش مائل للعربي ( المصري).\nإضافات :\nالدكتور رهيب كشرح , ودايما يدخل الكلاس وهو متبسم وللأمانه يخليك تفكر جديا انك تخصص كومنكيشن.\n\nEE203 LAB\nالتحضير :\n\nاول خمس دقايق وبعدها يعطيك ليت وبعد 10 دقايق ابسنت.\nطريقة الشرح :\nيشرح الكونسبت الي تحتاجه بشكل جدا واضح عل السبورة وبعدها تتوكل على الله بالاكسبريمنت .\nالكويزات :\nمتوسطة مائله للسهولة.\nالفاينلات :\nالاختبار العملي كان اشوي صعب , بس النظري كان سهل وماطلع من المنوال.\nالقريد النهائي:\nA\nإضافات :\nكان يعطي الاغلب 10 من 10 في الريبورتات والبري لاب , فممكن بعدها ينزلك الافرج.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1516625-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/31", "user": "Man.Moh", "ts": 1572537123000, "tid": 98387, "pn": 31}}]}', 1572537123000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_only-ee207', 'stk-_only', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98493", "n": "Dr. M Deriche", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده ee207 في فصل 101 … شرحه كان بالنسبه لي متوسط و مشكلته يشرحله الكونسيبت و يطول فيها و يهتم فيها أكثر من أنه يحل أسئلة و تمارين و في الواقع الإختبار نادر ما يجيك سؤال كونسيبت أغلبه أسئله حل بالأرقام و الرسم … كويزاته سهله … أخلاقه حلوه نوعا ما … تصحيحه متوسط … القريد النهائي b", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p898830-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-deriche/98493/4", "user": "_ONLY", "ts": 1315721856000, "tid": 98493, "pn": 4}}]}', 1315721856000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6095-ee207', 'stk-user6095', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98493", "n": "Dr. M Deriche", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 207 - Term 112\n\nالدكتور فآهم … و يشرح … و غآلبآ مآ يقضي الوقت على شرح الكونسبت …\n\nالنوتة اللي يكتبهآآ جدآآ ممتـآزة … و تغني عن الكتآب !!\n\nالصوت وآضح … و التحضير أحيآنآ …\n\nالكوزآت متوسطة غآلبــآ …\n\nيُنصح به …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049043-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-deriche/98493/8", "user": "user6095", "ts": 1338569290000, "tid": 98493, "pn": 8}}]}', 1338569290000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5689-ee207', 'stk-user5689', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98493", "n": "Dr. M Deriche", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مادة ال ee 207\n\nالدكتور متمكن من المادة بشكل عام , يشرح لك المهم , يجيب الملل بعض الشئ\n\nتصحيحه ممتاز وفوق الي تستحقه\n\nالقريد النهائي كان بالنسبه لي \"حلم \"\n\nأنصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1242972-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-deriche/98493/11", "user": "user5689", "ts": 1373119131000, "tid": 98493, "pn": 11}}]}', 1373119131000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_ali-ee207', 'stk-saleh_ali', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98508", "n": "Dr. Wajih Abu-Al-Saud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ee207--- 113\nالتحضير : يوزع ورقة وتوقع تو اسمك\nطريقة الشرح : ماشاء الله …افضل دكتور كهرب في الشرح مر علي …ويكتب نوت طيب ويشرح بامثلة طيبة\nالكويزات : سهله وفرصة لا تعوض\nالمياجر: ميجر ون جانا سهل وميجر تو حريقة\nالفاينلات : الفاينل جا متوسط اقرب الى السهل\nالقريد النهائي: A\nالصوت: مسموع\nإضافات : انصح به في اي مادة وتوكل على الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p889338-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wajih-abu-al-saud/98508/8", "user": "saleh_ali", "ts": 1313911293000, "tid": 98508, "pn": 8}}]}', 1313911293000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-am_1421-ee207', 'stk-am_1421', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98508", "n": "Dr. Wajih Abu-Al-Saud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مادة EE207 -- ترم 211\n\nالتحضير : يحضر نهاية كل حصة ومتساهل مع التاخير لكن لا تزودها 🙂\n\nطريقة الشرح : يعرض نوتته على ون نوت و طبعا يكتب عليها ويحل عليها بواسطة قلم السبورة الذكي… وشرح يصك في راسك ما عاد تنساه\nالكويزات : 5 كويزات وحذف اسوا كويز وكان مستواها متوسط … ورفعنا في النهاية كل واحد نص درجة 🙂\nالمياجر: كومن (متوسطة)\nالفاينلات : كومن ( صعب نوعا ما)\nالقريد النهائي: +A\nالصوت: عالي ما شاء الله وما يجيب النوم ابدا ويفهمك حتى لو ما تبغى تفهم\nإضافات :\n1 - الدكتور يبدأ خصم من أول غياب… طبعا حذف في النهاية غياب واحد.\n2- الدكتور جدا متعاون وطيب والله ويخاف على مصلحة الطالب ولكن حاجة وحدة شفتها سلبية نوعا ما … تصحيحه شوي شديد يعني الميجر الثاني ما يعطي بارشال على الخطوات لو اجابتك خطا.\n3- الكورس يعتبر صعب بس والله مع الدكتور وجيه حسيت الكورس خفيف وطلعت فيه ب +A معاه.\n\nالله يسعد الدكتور وجيه والله من خيرة الدكاترة شرحا وتعاملا وخلقا وناوي انزل عنده EE315 في الصيف 🙂\n\nفي النهاية أنصح فيه وبقوة جدا جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533424-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wajih-abu-al-saud/98508/23", "user": "AM_1421", "ts": 1641997212000, "tid": 98508, "pn": 23}}]}', 1641997212000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_side-ee207', 'stk-black_side', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98509", "n": "Dr. Husain Al-Jamed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أفضل دكتور درست عنده في قسم الكهرباء حتى الآن\n\nأخذت معه ee207\n\nطريقة الشرح :\n\nمن أول يوم في السمستر ينزل نوتات السمستر كله في البلاك بورد مكتوبه بيده, الأفضل انك تطبعها وتتبع معه في الكلاس لأنه يكتبها نفسها مع إضافة بعض التعليقات والتعديلات\nبكل صراحة أعتمدت فقط على نوتاته في المذاكرة وكانت مختصرة جداً مقارنة بدكاترة آخرين وتحتوي على زبدة الكورس مع أمثلة مناسبة\nالنتيجة أني حصلت على a+ الحمدلله اعتمادا على نوتاته فقط\n\nطبعاً كنت استمتع بمحاضرته صراحة, شخص له كاريزما عاجبتني جداً في الشرح وتحس أنه فعلا مو بس محضر للمحاضرة, تحس أنه حافظها عن ظهر غيب\n\nالكويزات:\n\nالكويزات عددهم 4 إلى 5 يحذف أسوأهم, ينزل قبل كل كويز هوموورك محلول وجاهز أنت فقط عليك أنت تذاكر النوتات وتتمرن على الهوموورك\nوالكويز بيكون بأفكار مشابهة جداً للهوموورك وطبعا الكويز عبار عن 4 أسئلة خيارات .\n\nالبروجكت :\n\nمن أكثر الأشياء اللي حببتني فيه, كنت أشوف أخوياي مع الدكاترة الثانين يستخدمون مات لاب وقضوا أكثر من يوم شغل على البروجكت\nاكتفيت أنا بمجهود ساعة فقط لعمل البروجكت حقه واللي كان سهل جداً وفقط يعتمد عالحسابات ومافيه أي حاجة للمات لاب.\n\nأعطيه a+ وأنا مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450337-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-jamed/98509/18", "user": "Black_side", "ts": 1464155018000, "tid": 98509, "pn": 18}}]}', 1464155018000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ee207', 'stk-mr.a1', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98509", "n": "Dr. Husain Al-Jamed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 162 EE 207\n\nالتحضير :\nبداية المحاضرة يمرر ورقة ، تكتب اسمك الاخير مع الرقم الجامعي. مرات قليلة شيّك على الورقة. التحضير ما عليه درجات طبعا. ما عنده مشكلة مع التأخير ، ولا يكلّم اللي يجون متأخرين.\n\nطريقة الشرح :\nكاملة على السبورة. عنده نوت متعوب عليها ينقل منها ويشرح. شرحه ممتاز.\n\nالكويزات :\nأخذنا ٤ كويزات طول الترم ، أعتقد كان يبي يعطينا خامس بس الوقت ما كان يساعد. انتبه من الكويزات معه ، كل كويز عليه تقريبا ٣٪‏ من المجموع النهائي.\n\nالمياجر:\nكومون. تصحيحه لأسئلة الريتن عادي ، بتاخذ حقك.\n\nالفاينلات :\nكومون ، باقي ما اختبرناه.\n\nالقريد النهائي:\nA+\n\nالصوت:\nكويس. المحاضرة كلها ما يقول كلمة عربية ، كله انجلش.\n\nإضافات :\n١. يعطيك أسئلة هوموركات في السيلبس ، لكنه ما يجمعها. ينزّل لك الحلول من بداية الترم ويختبرك كويزات على أسئلة الهومورك (مو نسخ لصق ، لكن مشابهة لها).\n٢. أعطانا بروجيكت نظري ، كان البروجيكت سهل ، وهو تساهل في التصحيح ، فأغلب السكشن أخذ درجة كاملة في البروجيكت.\n٣. الدكتور ما عنده مشكلة اذا تجي تنام في الكلاس أو تلعب بالجوال ، ولا راح يهتم بك أبد. أنت مسؤول عن نفسك.\n\nعموما الدكتور كويس ، وأنصح به. فيه كلام إنه راح يتقاعد بنهاية الترم ، لكن لو شفته مسجل مادة لا يفوتك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473785-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-jamed/98509/19", "user": "Mr.A1", "ts": 1495648075000, "tid": 98509, "pn": 19}}]}', 1495648075000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-euler-ee207', 'stk-euler', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98519", "n": "Dr. Azzedine Zerguine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 113 _ EE207\n\nبنود التقييم :\n\nالتحضير : يحضر بنص الكلاص وماعنده مشكلة بالتأخير , 🌹\n\nطريقة الشرح : يملي السبورة مرتين ماشاء الله عليه ويهتم بالطالب كثير ,+ يستخدم البروجكتر كثيير ,+ يحل مسائل قد مايقدر , ❤️\n\nالكويزات : اعطانا 8 كويزات واخذ احسن 5 كويزات , يعني يعطيك مجال كبير للتعويض , 🤴\n\nأسئلة الكويزات كانت مباشرة من أسئلة الهوموورك أو أسئلة الكتاب , يعني لو فاهم الهوموورك بتحل زين إن شاء الله , 🙂\n\nالمياجر: سكشنا كان الوحيد في ال 207 , فكان هو اللي يكتب الأسئلة , نكبنا في ميجر ون والافرج 51.4 % , وساعدنا ف ميجر تو والفاينال , 🌺\n\nالفاينلات : كان سهل والوقت كافي ولافي اي تركات , ويضع هنت أحيانا , 👍\n\nالقريد النهائي : أعطيه A+ , لاتفوته هذا إذا لقيت سكشنه فاتح , 🤴\n\nالصوت: واضح جدن , 🌹\n\nإضافات : إلى الآن ماشفنا القريدات وإن شاء الله مو مقصر معانا , 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1074960-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzedine-zerguine/98519/9", "user": "Euler", "ts": 1343913306000, "tid": 98519, "pn": 9}}]}', 1343913306000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8598-ee207', 'stk-user8598', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98519", "n": "Dr. Azzedine Zerguine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 121\nee207\n\nبنود التقييم :\n\nالتحضير :\nيحضر في نص الكلاس\nطريقة الشرح :\n\nدكتور شريح بكل ما تعنيه الكلمة من معنى ومهتم بالمادة وانك تفهم حتى لو يتأخر بالماتيريال اهم شي تفهم\nوقبل الميجر يسوي هلب سيشن يحل فيه مسائل ويوضح كل خطوة\n\nالكويزات :\nسهلة الى متوسطة ويحذف اسوأ كويز او اثنين ناسي\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nواااضح جدا\nإضافات :\nالدكتور اخلاق وشرحه ممتع والوضع مو كله سرد عادي يوقف الشرح وينكت شوي الكلاس معه فلة ولا تحس فيه\nوالتصحيح جيد اهون من غيره وانسان يدف في القريدات\n\nاحسن مافيه انه يهتم بالطلاب بعد ميجر تو لازم تجيه الاوفيس ويراجع درجاتك وكيف وضعك واذا ما كنت مبدع بيهزئك شوي\n\nالله يوفقه دنيا واخرة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1297042-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzedine-zerguine/98519/13", "user": "user8598", "ts": 1385775869000, "tid": 98519, "pn": 13}}]}', 1385775869000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mqr-ee207', 'stk-mqr', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98519", "n": "Dr. Azzedine Zerguine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "182-EE207\nبنود التقييم :\n\nبسم الله الرحمن الرحيم\n\nالتحضير :التحضير نهاية الحصة بس ما أذكر انه حضر عندنا . 😁\nطريقة الشرح :يشرح من النوته حقته وبرضوا يفتح الكتاب ويشرح منه ويعطيك مليون مثال الى ما تفهم الدرس وبختصار يعطيك امثلة على الاسئلة اللي بتجيك في الاختبار بختصار الدكتور مره أسطوري .طبعاً كنت في اول ثلاث اسابيع ضايع معاه بس من يوم ما بديت اكتب معاه وأحضر الهلب سشن حقته استفدت كثيرر.\nالكويزات :من سهله الى متوسطة نفس اللي يشرحه في الكلاس.\nالمياجر:كومن بسم غالبا تعتمد على اللي ماسك المادة في السمستر.\nالفاينلات :من متوسطة الى صعبة\nالقريد النهائي:ْA\nالصوت:واضح\nإضافات :\n1- الدكتور مره متعاون وحبيب تخش الحصة مراح تطفش مره الدكتور يحب يطقطق وينكت طول الحصة فدائم تبدء الحصة وتنتهي وأنت ما تحس.\n2-يعطيك حصص هلب سشن بالليل بعد ما يخلص كل شبتر هذي الحصص يحل فيها امثلة من الكتاب على الشبتر (افكار الاختبار).\n3-برضوا قبل كل ميجر او فاينل يعطيك هلب سشن تفيدك مره.\n4-الدكتور متعاون و يمشي في التصحيح\n5- الدكتور ما يحب أحد يسئله بعد الحصة ما تنتهي لانه يبي السؤال يستفيد منه كل الطلاب حتى لو تروح له الاوفس يمكن مرات يهزءك ويقولك ليش ما وقفتني وسئلتني في الحصة.\nبأختصار الدكتور مره أسطوري لو لقيته ننزل معاه وانت مغمض . :popcorn:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509144-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzedine-zerguine/98519/18", "user": "mqr", "ts": 1556534381000, "tid": 98519, "pn": 18}}]}', 1556534381000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-ee207', 'stk-user2352', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f98660", "n": "Dr. Magdi S. Mahmoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور غالبا شرحة سريع وما ينفهم\ncise315 انصحك تذاكر مع واحد من اخوياك طلاب الكهرباء ee207\nلأنه نفس الكورس والدكتور مجدي ياخذ من مياجر نفس الكورس ee207\nعلى كلام واحد من الخريجين اعرفه ينصح إنك تذاكر من نوتة د. الجامد قسم الكهرباء ee207 تحصلها في موقع الريسورس\nوتحل مسائل hw مع اولد اقزام ee207 لأنه تقريبا نفس الكورس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1426649-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-magdi-s-mahmoud/98660/4", "user": "user2352", "ts": 1441027539000, "tid": 98660, "pn": 4}}]}', 1441027539000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-1zezo1-ee207', 'stk-1zezo1', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f152929", "n": "Dr. Ibrir Saleem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 207 - TERM 143\n\nالتحضير : نادرا كان يحضر\nطريقة الشرح : يستخدم السلايدات والسبورة…شرحه أقل من المتوسط\nالكويزات :متوسطة\nالمياجر:متوسطة\nالفاينلات :متوسطة\nالقريد النهائي: D+\nالصوت:اللغة عنده سيئة والصوت عادي لاهو عالي ولا منخفض\nإضافات : مازلت أكرر واٌقول انه مو كل من أخذ دكتوراة يعرف يشرح…لازم ياخذوا دورات تدريس…غير متعاون في office hour\nطلب مننا نثبت بعض القوانين في Fourier series…أخذت مني تقريبا خمس ساعات اثنين منها كان فيها أخطاء\nويوم راجعته ما طالع في الورقة عالأقل قال اذا غلط روح حلها مرة ثانية\n😠 😠 :zipper_mouth_face:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440017-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrir-saleem/152929/6", "user": "1zezo1", "ts": 1453339486000, "tid": 152929, "pn": 6}}]}', 1453339486000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmahm50-ee207', 'stk-ahmahm50', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f175780", "n": "Dr. Mudassir Masood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T-162 EE-207\nالتحضير : نهاية المحاضرة ينادي على الأسماء . كان متشدد على التحضير لكنه حذف غيابات اول اسبوع.\nطريقة الشرح : ممتازة. يجي وهو محضر كل شي و يشرح لنا على السبورة و يحل أمثلة كافية لفهم الأساسيات .\nالكويزات : سهلة .\nالمياجر: كومن.\nالفاينلات : كومن.\nالقريد النهائي: A\nالصوت: واضح.\nإضافات :\n1- في بداية الكورس واجهت صعوبة في فهم المادة من الدكتور مادري لان الكورس جديد علي ولا من طريقة توصيله للمعلومه، لكن بعدين تعودت عليه و صار الوضع تمام.\n2- الدكتور كان شرحه ممتاز لكن هالمادة الشرح الممتاز لحاله ما يكفي لها. لازم تحل مسائل قد ما تقدر فيها.\n3- الدكتور متخصص في ال Digital Signal Processing و هاذي ميزة لانه كان يجاوب على أسئلة كثيره شاطحة من الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479214-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mudassir-masood/175780/4", "user": "ahmahm50", "ts": 1503529225000, "tid": 175780, "pn": 4}}]}', 1503529225000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muntathir111-ee207', 'stk-muntathir111', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f175780", "n": "Dr. Mudassir Masood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE207 - TERM192\nبقيم اعتمادا عليه قبل الاونلاين\nالتحضير : ورقة تمشي على الكلاس\nوايضا قالنا ببداية السمستر ماراح اخصم على الغياب بس فيه DN\nطريقة الشرح : بالسبورة واحيانا سلايدات (يعتمد على الدرس وافكاره والدكتور يحب يوصل المعلومة بافضل طريقة)\nطبعا اشوف شرحه ب207 لا يعلى عليه جدا ممتاز وواضح\nالكويزات : متفاوتة احيانا سهلة واحيانا وسط واحيانا جلدد\nالمياجر: تعتمد على الكوردنيتر. طبعا هنا اعظم سلبية للدكتور وهي تصحيحه. الدكتور يدقق بالملي وتصحيحه ظالم نوعا ما (اتذكر راجعت الميجر حقي وشفت فيه نقاط بسلوشن الميجر ماحسبها لي فكلمته عليها وزادني شوي وقال بيكلم الكوردنيتر عليها )\nالفاينلات :\nالقريد النهائي: A بحكم ان الكورس يحتاج دكتور شريح\nالصوت: واضح جدا\nإضافات :\nالدكتور يهتم حيل بفهم الطلاب للافكار الاساسية لدرجة انه عادي يتأخر بالمنهج . بس مشكلته اذا تأخر بيمشي على بعض السكاشن الفرعية بسرعة وبيطلب من الطلاب يقرون الكتاب ويفهمونها بنفسهم.\nبصراحة اذا كانت المادة دسمة وتحتاج فهم شديد مثل 207 انصح تنزلون عنده وبترتاحون بس مشكلته بالتصحيح.\nايضا درست عنده لاب213 بنفس السمستر وكان ممتاز ومتساهل باللاب.\nاخر نقطة الا وهي ان الدكتور يمسك كم طالب من بداية السمستر ويسألهم كل كلاس\nانا درست عنده بسكشنين فحفظني بسرعة وكنت منهم 😡 😭\nكل كلاس بوقت عشوائي يمسكني ويسألني سؤال عشوائي بالدرس هههههههههههه بالنسبة لي تقبلت الموضوع بروح رياضية وصرت اركز اكثر بالكلاس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521990-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mudassir-masood/175780/8", "user": "Muntathir111", "ts": 1589263998000, "tid": 175780, "pn": 8}}]}', 1589263998000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11634-ee207', 'stk-user11634', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f175780", "n": "Dr. Mudassir Masood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 192 - EE 207 - قبل الدراسة عن بعد بسبب كورونا\n\nالتحضير : ورقة يمررها على الطلاب.\nطريقة الشرح :\nالدكتور مهتم جدا بفهم الطالب، لذلك عندما يشرح المفاهيم الجديدة يمهد لها بشكل جيد عن طريق شرح مفاهيم سابقة متعلقة بها حتى لو لم تكن مطلوبة في المقرر، ويبدأ بشرح المفهوم من أبسط جزئية فيه ثم يتدرج، مثلا، عند اشتقاق القوانين يشرح كل الخطوات بالتفصيل، كذلك يربط المفاهيم بتطبيقاتها بشكل رائع، لكن في أحيان قليلة يطلب من الطلاب قراءة بعض الجزئيات الفرعية في المفهوم لوحدهم من الكتاب بسبب عامل الوقت والتأخر في المقرر، ويشرح باستخدام السبورة عند الاشتقاقات وحل المسائل، وفي غير ذلك يستخدم السلايدات.\nالكويزات : كويزاته صعبة نسبيا، وتحتاج مذاكرة جيدة، لكن بوجود الـ Normalization لا خوف منها للطالب المجتهد.\nالمياجر: موحدة\nالفاينلات: لم يؤخذ NP بسبب كورونا\nالقريد النهائي: +A ( باستثناء التصحيح )\nالصوت: واضح ولغته الإنجليزية ممتازة\nإضافات:\nيعيب الدكتور تدقيقه الشديد في التصحيح، لدرجة أنه حتى تسمية الـ axes عند رسم الـ signals يخصم عليها، حتى لو كان اسم الـ signal واضح من السؤال، وفي الميجر ممكن بسبب دقته هذه يخصم على طلابه أكثر مما لو كان دكتور آخر يصحح، لذلك أعتقد هذه أهم نقطة تؤخذ بعين الاعتبار عند اختيار الدكتور مدثر مسعود، وأن يكون الطالب مستعدا دائما لإعطاء إجابات شبه نوذجية إذا أراد تجنب الخصم كليا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524215-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mudassir-masood/175780/9", "user": "user11634", "ts": 1595763140000, "tid": 175780, "pn": 9}}]}', 1595763140000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mzd-ee207', 'stk-mzd', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f176830", "n": "Dr. Ali Arshad Nasir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T-212 EE207\n\nالتحضير : احيانا بداية المحاضرة ومرات نهاية المحاضرة، مرات يحضر ومرات لا.\n\nطريقة الشرح : يستعمل الشاشة لعرض السلايدات ويستخدم السبورة في شرح وحل الأمثلة، الدكتور يركز على الجانب الرياضي بشكل كبير وكان دايم يشرح اثبات القوانين كيف جبنا هذا القانون، احيانا كان يعطينا تطبيقات على الاشياء الا ندرسها. شرحه بشكل عام ممتاز اذا كنت مركز معه.\n\nالكويزات : الكويزات نار صعبه جدا والافرج غالبا يكون نازل مره. وغالبا تكون بعد نهاية كل شابتر.\n\nالمياجر: كومن\nالفاينلات : كومن\nالتصحيح: تصحيحه عادي، لكن لازم تراجع تصحيحه لانه احيانا يكون مستعجل في التصحصيح وينقصك وانت اجابتك صحيحه، لازم تراجع بعده.\n\nالقريد النهائي: ِ A\nالصوت: جدا واضح، ولهجته ممتازة\n\nإضافات :\n- الدكتور حبيب واخلاقه ممتازة مشاء الله.\n- الدكتور كان دايم قبل كل ميجر يشجعنا ويقول لاختبار سهل ومقدور عليه، بس مرات يكون الاختبار صعب مره ونجلد 🙂\n- الدكتور يركز على الجانب الرياضي بشكل كبير مره في شرحه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534479-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-arshad-nasir/176830/7", "user": "MZD", "ts": 1653692426000, "tid": 176830, "pn": 7}}]}', 1653692426000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khc800-ee207', 'stk-khc800', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f181421", "n": "Dr. Fahhad Al Harbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE207/182\n\nالتحضير : الدكتور ما يحضر أبدا، ولكن في نفس الوقت ما يبغى أحد يغيب.\nطريقة الشرح : سلايدات من إعداد الدكتور كان يجهزها قبل كل محاضرة، مختصرة لا تكفي لحالها للمذاكرة. يركز على الأفكار والفهم كثير عن طريق طرح الأسئلة ويطلعنا أحيانا على السبورة نشتق بعض المعادلات. من فترة لفترة يسوي problem solving session قبل المياجر والفاينل.\nالكويزات : كويزاته متوسطة، يركز فيها على الأشياء اللي كان يقولها في الكلاس.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح جدا، إنجليزية ممتازة.\nإضافات : الدكتور حبيب جدا ومتعاون وحريص على مصلحة الطالب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509327-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahhad-al-harbi/181421/2", "user": "khc800", "ts": 1556951140000, "tid": 181421, "pn": 2}}]}', 1556951140000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ee207', 'stk-guest', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f181421", "n": "Dr. Fahhad Al Harbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE207 الفصل 201 أون لاين\n\nالتحضير :\nما كان يقول لنا عن التحضير لكن اعتقد أنه ياخذه بدون ما يقول لنا لكن عامة ما سمعت أن طالب اشتكى من التحضير.\n\nطريقة الشرح :\nكان مقسم الشاشة نصفين الأول بورد فاضي يكتب عليه والثاني هي سلايدات خاصة فيه وشرحه واضح. طريقة الشرح السلايدات تكون فيها رؤوس اقلام وهو يوضحها بالبورد اللي على اليمين بإختصار كأنك بكلاس. بما أن الكورس غالبه ماث فكان الدكتور يحب يوضح لنا من وين جات المفاهيم وغيره واشوفه شي كويس بالإضافة إلى أنه يحل امثلة على كل كونسبت يشرحه ويحب مشاركة الطلاب فكان لمّ يحل لازم الطلاب يشاركون معه وينوع إذا شاف طالب ما شارك ورفع يده يقدمه على الطالب اللي شارك من قبل وكان في امثلة تكون بمفاهيم مهمة فيقول لطلاب أنا بحلها عشان يتأكد أن جميع الطلاب فاهمينها.\n\nالكويزات :\nسهلة إلى متوسطة والدكتور جزاه الله خير كان متساعد أول كويز كان الأفرج نازل سوى إعادة للكويز واعتبره بونص للطلاب اللي جابوا كويس بعدها الكويزات كانت غالبًا سهلة ويغلب عليها الاختياري إن ما كانت كلها اختياري.\n\nالمياجر:\nحولوها لميد وكانت صراحة معقولة جدًا الاختبار مقسم لجزئين الأول اختياري والثاني رتن.\n\nالفاينلات :\nنفس الميد.\n\nالقريد النهائي:\nالكورس الحمدلله طلعت بقريد A.\n\nالدكتور اعطيه قريد A+ ولو في اعلى عطيته ، الدكتور كان أكثر دكتور متساعد خلال الترم حتى بالكويزات يشارونا بالوقت المناسب لنا يعطينا الواجبات بأوقات ما فيها ضيق أو انشغال بالإضافة يقبل التأخير بالواجب لكن بتفقد شي بسيط من الدرجة بدام ما بالغت بالتأخير. بالإضافة تساعد معنا بالكلاس ورك بشكل كبير حذف لنا اسوأ كويز واسوأ واجب بالإضافة حذف لنا اختبارين شورت تست عليهم 15% وخذ بدالها درجة أفضل كويزين.\n\nالصوت:\nواضح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527693-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahhad-al-harbi/181421/5", "user": "Guest", "ts": 1610077590000, "tid": 181421, "pn": 5}}]}', 1610077590000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dark_side-ee207', 'stk-dark_side', 'EE 207', 'doc', '{"docs": [{"id": "stk-dr-f181421", "n": "Dr. Fahhad Al Harbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE207-T222\n\nالتحضير:\nيوميا التحضير بوسط الكلاس يعطي ورقه توقيع تمر على الطلاب، و كان معطينا غيابين ماراح يخصم عليها\nالدكتور متشدد بخصوص التحضير\n\nطريقة الشرح:\nالدكتور عنده سلايدات خاصه فيه يعتمد عليها ب الشرح وتحتوي على اسئله يحلها مع الطلاب ب السبوره.\nالدكتور يعتمد بشكل كبير جدا على اشتقاقات المعادله وكيف صارت كذا المعادله و وش اساسها…\n\nالحقيقه انا ماجاز لي اسلوبه بالشرح ابدا لاني م احب اقعد اشوف الاشتقاقات وكنت ماخذ الكورس سلف ستدي و اشوف مقاطع الدكتور مصباح باليوتيوب وكان الوضع والله ضياع لكن الحمدالله تخارجنا ب قريد\n\nالكويزات:\nمتوسطه مائله للسهوله و اغلبها من اسئلة الكتاب و اخر السمستر يحذف لك اسوء كويز و اسوء واجب.\n\nالقريد النهائي للدكتور:\n\nB\n\nاضافات:\n\nالدكتور شديد بخصوص الجوالات و بخصوص التأخير جدا توصل لطردك من الكلاس اذا شافك ب الجوال و الجو ب الكلاس سيء الصراحه بالنسبه لي الدكتور من النوع اللي مسوي شديد و اشوف ذا النظام ينفع ل ابتدائيه ولا طلاب متوسطه لكن جامعيين و اسلوبك كذا معهم شيء غريب الصراحه و ان شاءالله يتعدل مستقبلا\n\nنقطه ثانيه بخصوص وقت الكويزات و الواجبات\nالدكتور غير متساعد ب التأجيل ابدا، فيه اسبوع عندنا ب كان الاغلب عنده مياجر فيه و حوسه و الدكتور حط كويزه و حط واجب فيه و جينا كلمناه و حاولنا فيه لكن مافيه تجاوب و اخر شيء الاغلب لقم ب الكويز و الافرج حق الكويز حول ٤ من ١٠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536746-ee207", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahhad-al-harbi/181421/6", "user": "Dark_Side", "ts": 1686239519000, "tid": 181421, "pn": 6}}]}', 1686239519000, 1794826852, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
